from datetime import datetime


def main() -> dict:
    return {
        "current_date": datetime.now().strftime("%Y-%m-%d"),
    }

def main(is_error, content) -> dict:
    final_decision = "NEW"

    try:
        if is_error == 0 and content:
            text = content[0].get("text", "") if isinstance(content[0], dict) else ""
            key = '"final_decision"'
            idx = text.find(key)
            if idx != -1:
                # 定位到冒号后第一个引号
                start = text.find('"', idx + len(key))
                if start != -1:
                    end = text.find('"', start + 1)
                    if end != -1:
                        value = text[start + 1:end]
                        if value in ("NEW", "REUSE"):
                            final_decision = value
    except Exception:
        pass

    return {
        "result": final_decision,
    }

